from __future__ import annotations

import argparse
from dataclasses import dataclass
from datetime import datetime, timedelta, timezone
from email import policy
from email.header import decode_header, make_header
from email.message import EmailMessage, Message
from email.parser import BytesParser
from email.utils import parsedate_to_datetime
import imaplib
import json
import logging
from pathlib import Path
import re
import sys
import time

from config import MailReaderConfig
from storage import append_jsonl, ensure_parent, load_processed_ids, save_processed_ids, write_json


EMAIL_PATTERN = re.compile(r"[\w.!#$%&'*+/=?^_`{|}~-]+@[\w-]+(?:\.[\w-]+)+")
REPLY_SUBJECT_PATTERN = re.compile(r"^\s*(?:re|fwd?|fw)\s*:", re.IGNORECASE)
result: object = None


@dataclass(frozen=True)
class ParsedEmail:
    uid: str
    message_id: str | None
    sender: str
    subject: str
    received_at: str
    body: str


def setup_logging(log_path: Path) -> None:
    ensure_parent(log_path)
    logging.basicConfig(
        level=logging.INFO,
        format="%(asctime)s %(levelname)s %(message)s",
        handlers=[
            logging.FileHandler(log_path, encoding="utf-8"),
        ],
    )


def decode_mime(value: str | None) -> str:
    if not value:
        return ""
    return str(make_header(decode_header(value)))


def message_body(message: Message) -> str:
    if message.is_multipart():
        plain_parts: list[str] = []
        fallback_parts: list[str] = []

        for part in message.walk():
            content_disposition = part.get_content_disposition()
            content_type = part.get_content_type()
            if content_disposition == "attachment":
                continue

            if content_type == "text/plain":
                plain_parts.append(_part_text(part))
            elif content_type == "text/html":
                fallback_parts.append(strip_html(_part_text(part)))

        return "\n".join(part for part in plain_parts or fallback_parts if part).strip()

    return _part_text(message).strip()


def _part_text(part: Message) -> str:
    payload = part.get_payload(decode=True)
    if payload is None:
        raw = part.get_payload()
        return raw if isinstance(raw, str) else ""
    charset = part.get_content_charset() or "utf-8"
    return payload.decode(charset, errors="replace")


def strip_html(value: str) -> str:
    value = re.sub(r"(?is)<(script|style).*?>.*?</\1>", " ", value)
    value = re.sub(r"(?s)<br\s*/?>", "\n", value)
    value = re.sub(r"(?s)</p\s*>", "\n", value)
    value = re.sub(r"(?s)<.*?>", " ", value)
    return re.sub(r"[ \t]+", " ", value)


def parse_message(uid: str, raw_message: bytes) -> ParsedEmail:
    message = BytesParser(policy=policy.default).parsebytes(raw_message)
    received_at = _received_at(message)

    return ParsedEmail(
        uid=uid,
        message_id=decode_mime(message.get("Message-ID")) or None,
        sender=decode_mime(message.get("From")),
        subject=decode_mime(message.get("Subject")),
        received_at=received_at,
        body=message_body(message),
    )


def _received_at(message: EmailMessage | Message) -> str:
    raw_date = message.get("Date")
    if raw_date:
        try:
            parsed = parsedate_to_datetime(raw_date)
            if parsed.tzinfo is None:
                parsed = parsed.replace(tzinfo=timezone.utc)
            return parsed.isoformat()
        except (TypeError, ValueError):
            pass
    return datetime.now(timezone.utc).isoformat()


def build_search_query(config: MailReaderConfig, now: datetime | None = None) -> str:
    parts = [config.email_search_criteria or "UNSEEN"]
    if config.email_lookback_hours > 0:
        cutoff = _lookback_cutoff(config, now)
        parts.extend(["SINCE", cutoff.astimezone().strftime("%d-%b-%Y")])
    if config.email_from_filter:
        parts.extend(["FROM", f'"{config.email_from_filter}"'])
    if config.email_subject_filter:
        parts.extend(["SUBJECT", f'"{config.email_subject_filter}"'])
    return " ".join(parts)


def _lookback_cutoff(config: MailReaderConfig, now: datetime | None = None) -> datetime:
    current_time = now or datetime.now(timezone.utc)
    if current_time.tzinfo is None:
        current_time = current_time.replace(tzinfo=timezone.utc)
    return current_time.astimezone(timezone.utc) - timedelta(hours=config.email_lookback_hours)


def is_within_lookback(
    parsed: ParsedEmail,
    config: MailReaderConfig,
    now: datetime | None = None,
) -> bool:
    if config.email_lookback_hours <= 0:
        return True

    try:
        received_at = datetime.fromisoformat(parsed.received_at)
    except ValueError:
        logging.warning(
            "Could not parse received_at for UID %s, keeping message in candidate set: %s",
            parsed.uid,
            parsed.received_at,
        )
        return True

    if received_at.tzinfo is None:
        received_at = received_at.replace(tzinfo=timezone.utc)

    return received_at.astimezone(timezone.utc) >= _lookback_cutoff(config, now)


def connect(config: MailReaderConfig) -> imaplib.IMAP4_SSL:
    mailbox = imaplib.IMAP4_SSL(config.email_host, config.email_port)
    mailbox.login(config.email_username, config.email_password)
    status, _ = mailbox.select(config.email_folder)
    if status != "OK":
        raise RuntimeError(f"Unable to select mailbox folder: {config.email_folder}")
    return mailbox


def fetch_uids(mailbox: imaplib.IMAP4_SSL, search_query: str) -> list[str]:
    status, data = mailbox.uid("search", None, search_query)
    if status != "OK":
        raise RuntimeError(f"IMAP search failed for query: {search_query}")
    return data[0].decode("ascii").split() if data and data[0] else []


def fetch_message(mailbox: imaplib.IMAP4_SSL, uid: str) -> bytes:
    status, data = mailbox.uid("fetch", uid, "(BODY.PEEK[])")
    if status != "OK":
        raise RuntimeError(f"Unable to fetch message UID {uid}")

    for item in data:
        if isinstance(item, tuple) and item[1]:
            return item[1]
    raise RuntimeError(f"No message payload returned for UID {uid}")


def mark_read(mailbox: imaplib.IMAP4_SSL, uid: str) -> None:
    mailbox.uid("store", uid, "+FLAGS", "(\\Seen)")


def extract_contact(parsed: ParsedEmail, config: MailReaderConfig) -> dict[str, str] | None:
    if is_reply_or_forward(parsed.subject):
        logging.info(
            "Skipped UID %s because it appears to be a reply/forward. Subject=%r",
            parsed.uid,
            parsed.subject,
        )
        return None

    searchable = "\n".join([parsed.subject, parsed.sender, parsed.body])
    fields = _parse_labeled_fields(searchable)

    message = fields.get("message") or _extract_message(parsed.body)

    if not has_required_contact_form_fields(fields, message):
        logging.info(
            "Skipped UID %s because it does not contain the required contact form fields. Subject=%r",
            parsed.uid,
            parsed.subject,
        )
        return None

    contact_email = fields.get("email") or _first_contact_email(searchable, parsed.sender)
    contact_name = fields.get("name", "")
    interested_in = fields.get("interested in", "")

    if not contact_email:
        return None

    return {
        "source_email_id": parsed.uid,
        "message_id": parsed.message_id or "",
        "contact_name": contact_name,
        "contact_email": contact_email,
        "company": fields.get("company", ""),
        "interested_in": interested_in,
        "form_timestamp": fields.get("timestamp", ""),
        "ip": fields.get("ip", ""),
        "country": fields.get("country", "").upper(),
        "message": message,
        "subject": parsed.subject,
        "received_at": parsed.received_at,
        "status": "new_contact",
    }


def normalize_contact_name(value: object) -> str:
    return "".join(character for character in str(value or "").casefold() if character.isalnum())


def contact_spam_reasons(contact: dict[str, str], config: MailReaderConfig) -> list[str]:
    reasons: list[str] = []
    contact_ip = str(contact.get("ip") or "").strip()
    blocked_names = {
        normalize_contact_name(name)
        for name in config.blocked_contact_names
        if normalize_contact_name(name)
    }
    if contact_ip and contact_ip in config.blocked_contact_ips:
        reasons.append("blocked_ip")
    if normalize_contact_name(contact.get("contact_name")) in blocked_names:
        reasons.append("blocked_name")
    return reasons


def quarantine_contact(
    contact: dict[str, str],
    reasons: list[str],
    config: MailReaderConfig,
) -> None:
    quarantined = dict(contact)
    quarantined.update(
        {
            "status": "blocked_spam",
            "spam_reasons": sorted(set(reasons)),
            "blocked_at": datetime.now(timezone.utc).isoformat(),
        }
    )
    append_jsonl(config.blocked_contacts_path, quarantined)


def is_reply_or_forward(subject: str) -> bool:
    return bool(REPLY_SUBJECT_PATTERN.match(subject or ""))


def has_required_contact_form_fields(fields: dict[str, str], message: str) -> bool:
    return bool(fields.get("name") and fields.get("email") and message)


def _parse_labeled_fields(text: str) -> dict[str, str]:
    fields: dict[str, str] = {}
    lines = text.splitlines()
    for index, line in enumerate(lines):
        match = re.match(r"^\s*([A-Za-z][A-Za-z ]{1,40})\s*:\s*(.*?)\s*$", line)
        if not match:
            continue

        key = re.sub(r"\s+", " ", match.group(1).strip().lower())
        value = match.group(2)
        if not value and key == "message":
            value = _value_after_label(lines, index + 1)
        if value:
            fields[key] = _clean_value(value)
    return fields


def _value_after_label(lines: list[str], start_index: int) -> str:
    values: list[str] = []
    for line in lines[start_index:]:
        if re.match(r"^\s*[A-Za-z][A-Za-z ]{1,40}\s*:\s*", line):
            break
        values.append(line)
    return "\n".join(values).strip()


def _first_contact_email(text: str, sender: str) -> str | None:
    candidates = EMAIL_PATTERN.findall(text)
    sender_emails = set(EMAIL_PATTERN.findall(sender))
    for candidate in candidates:
        if candidate not in sender_emails:
            return candidate
    return candidates[0] if candidates else None


def _extract_message(text: str) -> str:
    match = re.search(r"(?ims)^\s*Message\s*:\s*(.*?)\s*$", text)
    if not match:
        return ""
    return match.group(1).strip()[:5000]


def _clean_value(value: str) -> str:
    value = re.sub(r"\s+", " ", value).strip()
    return value[:200]


def workflow_contact_payload(contact: dict[str, str]) -> dict[str, str]:
    return {
        "Name": contact.get("contact_name", contact.get("Name", "")),
        "Email": contact.get("contact_email", contact.get("Email", "")),
        "Company": contact.get("company", contact.get("Company", "")),
        "Interested In": contact.get("interested_in", contact.get("Interested In", "")),
        "Message": contact.get("message", contact.get("Message", "")),
        "IP": contact.get("ip", contact.get("IP", "")),
        "Country": contact.get("country", contact.get("Country", "")),
    }


def format_contact_for_workflow(contact: dict[str, str]) -> str:
    payload = workflow_contact_payload(contact)
    return "\n".join(
        [
            f"- Name: {payload['Name']}",
            f"- Email: {payload['Email']}",
            f"- Company: {payload['Company']}",
            f"- Interested In: {payload['Interested In']}",
            f"- Message: {payload['Message']}",
            f"- IP: {payload['IP']}",
            f"- Country: {payload['Country']}",
        ]
    )


def print_contact_summary(contact: dict[str, str]) -> None:
    print(format_contact_for_workflow(contact), flush=True)


def print_workflow_result(payload: object) -> None:
    if isinstance(payload, dict) and payload.get("status") == "no_new_contacts":
        print("No New Contacts", flush=True)
        return
    if isinstance(payload, dict):
        print(format_contact_for_workflow(payload), flush=True)


def no_new_contacts_result() -> dict[str, str]:
    return {"status": "no_new_contacts"}


def run_once(config: MailReaderConfig) -> list[dict[str, str]]:
    processed_ids = load_processed_ids(config.processed_emails_path)
    new_contacts: list[dict[str, str]] = []
    now = datetime.now(timezone.utc)
    search_query = build_search_query(config, now)

    logging.info("Connecting to %s folder %s", config.email_host, config.email_folder)
    mailbox = connect(config)
    try:
        uids = fetch_uids(mailbox, search_query)
        logging.info("Found %s candidate messages for query: %s", len(uids), search_query)

        for uid in uids:
            if uid in processed_ids:
                logging.info("Skipped UID %s because it is already in %s.", uid, config.processed_emails_path)
                if config.email_mark_read:
                    mark_read(mailbox, uid)
                continue

            parsed = parse_message(uid, fetch_message(mailbox, uid))
            if not is_within_lookback(parsed, config, now):
                logging.info(
                    "Skipped UID %s because it is outside the %s-hour lookback.",
                    uid,
                    config.email_lookback_hours,
                )
                continue

            contact = extract_contact(parsed, config)
            if not contact:
                logging.warning(
                    "Skipped UID %s because contact email could not be parsed. Subject=%r",
                    uid,
                    parsed.subject,
                )
                continue

            spam_reasons = contact_spam_reasons(contact, config)
            if spam_reasons:
                quarantine_contact(contact, spam_reasons, config)
                if config.email_mark_read:
                    mark_read(mailbox, uid)
                    logging.info("Marked quarantined UID %s as read.", uid)
                processed_ids.add(uid)
                logging.warning(
                    "Quarantined spam contact UID %s. Reasons=%s Name=%r IP=%r",
                    uid,
                    ",".join(spam_reasons),
                    contact.get("contact_name", ""),
                    contact.get("ip", ""),
                )
                continue

            append_jsonl(config.contact_output_path, contact)

            if config.email_mark_read:
                mark_read(mailbox, uid)
                logging.info("Marked UID %s as read.", uid)

            processed_ids.add(uid)
            new_contacts.append(workflow_contact_payload(contact))

        save_processed_ids(config.processed_emails_path, processed_ids)

        return new_contacts
    finally:
        mailbox.logout()


def run_loop(config: MailReaderConfig) -> None:
    while True:
        try:
            contacts = run_once(config)
            logging.info("Mail reader cycle complete. Parsed %s new contact records.", len(contacts))
        except Exception:
            logging.exception("Mail reader cycle failed")
        time.sleep(config.email_poll_seconds)


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Read website contact emails and write contact records.")
    parser.add_argument("--once", action="store_true", help="Run one mailbox scan and exit. This is the default.")
    parser.add_argument("--loop", action="store_true", help="Keep scanning every EMAIL_POLL_SECONDS.")
    return parser.parse_args()


def main() -> None:
    global result
    args = parse_args()
    config = MailReaderConfig.from_env()
    setup_logging(config.mail_reader_log_path)

    if args.loop:
        run_loop(config)
        return

    contacts = run_once(config)
    if contacts:
        latest_contact = contacts[0]
        write_json(config.latest_contact_path, latest_contact)
        print_workflow_result(latest_contact)
        result = latest_contact
    else:
        result = no_new_contacts_result()
        print_workflow_result(result)
    logging.info("Parsed %s new contact records.", len(contacts))


if __name__ == "__main__":
    main()

from __future__ import annotations

import argparse
from dataclasses import dataclass
from datetime import datetime, timezone
import fcntl
import json
import os
from pathlib import Path
import re
import sys
from urllib.parse import urlparse


URL_PATTERN = re.compile(r"(?i)\b(?:https?://|www\.)[^\s<>]+")
PROMOTIONAL_PATTERNS = (
    re.compile(r"(?i)\bpromo(?:tional)?\s+code\b"),
    re.compile(r"(?i)\b(?:coupon|discount)\s+code\b"),
    re.compile(r"(?i)\b(?:prize|lottery|sweepstakes|winner|giveaway)\b"),
    re.compile(r"(?i)\b(?:bitcoin|crypto(?:currency)?|casino|gambling)\b"),
    re.compile(r"(?i)\b(?:backlinks?|guest\s+posts?|search\s+engine\s+optimization|SEO)\b"),
    re.compile(r"(?i)\b(?:guaranteed\s+traffic|click\s+here|limited\s+time)\b"),
)
UNKNOWN_COUNTRIES = {"", "XX"}
result: object = None


def _load_env_file(path: Path = Path(".env")) -> None:
    if not path.exists():
        return
    for raw_line in path.read_text(encoding="utf-8").splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        key, value = line.split("=", 1)
        os.environ.setdefault(key.strip(), value.strip().strip('"').strip("'"))


    unfilled = sorted(k for k, v in os.environ.items() if v.startswith("ENTER_") and v.endswith("_HERE"))
    if unfilled:
        raise SystemExit(f"Fill in {', '.join(unfilled)} in {path} before running this workflow.")


def csv_values(value: str) -> frozenset[str]:
    return frozenset(item.strip() for item in str(value or "").split(",") if item.strip())


def normalize_name(value: object) -> str:
    return "".join(character for character in str(value or "").casefold() if character.isalnum())


@dataclass(frozen=True)
class ScreeningConfig:
    allowed_countries: frozenset[str]
    blocked_names: frozenset[str]
    blocked_ips: frozenset[str]
    blocked_domains: frozenset[str]
    screened_path: Path
    blocked_path: Path
    review_path: Path
    minimum_message_length: int = 20

    @classmethod
    def from_env(cls) -> "ScreeningConfig":
        _load_env_file()
        return cls(
            allowed_countries=frozenset(
                country.upper()
                for country in csv_values(
                    os.getenv("CONTACT_ALLOWED_COUNTRIES", "US,PR,VI,GU,AS,MP")
                )
            ),
            blocked_names=frozenset(
                normalize_name(name)
                for name in csv_values(
                    os.getenv("BLOCKED_CONTACT_NAMES", "RobertWew,HarryPhefs")
                )
            ),
            blocked_ips=csv_values(
                os.getenv(
                    "BLOCKED_CONTACT_IPS",
                    "77.90.185.5,141.98.11.224,80.94.95.173,158.173.20.36",
                )
            ),
            blocked_domains=frozenset(
                domain.casefold()
                for domain in csv_values(os.getenv("BLOCKED_CONTACT_DOMAINS", "jbiv.com"))
            ),
            screened_path=Path(
                os.getenv("SCREENED_CONTACTS_PATH", "data/screened_contacts.jsonl")
            ),
            blocked_path=Path(
                os.getenv("BLOCKED_CONTACTS_PATH", "data/blocked_contacts.jsonl")
            ),
            review_path=Path(
                os.getenv("REVIEW_CONTACTS_PATH", "data/review_contacts.jsonl")
            ),
            minimum_message_length=max(
                1, int(os.getenv("CONTACT_MINIMUM_MESSAGE_LENGTH", "20"))
            ),
        )


def parse_contact(value: object) -> dict[str, str]:
    if isinstance(value, dict):
        if is_no_new_contact(value):
            return {"status": "no_new_contacts"}
        payload = value
    else:
        text = str(value or "").strip()
        if is_no_new_contact(text):
            return {"status": "no_new_contacts"}
        try:
            decoded = json.loads(text)
        except json.JSONDecodeError:
            decoded = _parse_labeled_text(text)
        payload = decoded if isinstance(decoded, dict) else {}
    return {
        "Name": str(payload.get("Name") or payload.get("contact_name") or "").strip(),
        "Email": str(payload.get("Email") or payload.get("contact_email") or "").strip(),
        "Company": str(payload.get("Company") or payload.get("company") or "").strip(),
        "Interested In": str(
            payload.get("Interested In") or payload.get("interested_in") or ""
        ).strip(),
        "Message": str(payload.get("Message") or payload.get("message") or "").strip(),
        "IP": str(payload.get("IP") or payload.get("ip") or "").strip(),
        "Country": str(payload.get("Country") or payload.get("country") or "")
        .strip()
        .upper(),
    }


def _parse_labeled_text(text: str) -> dict[str, str]:
    fields: dict[str, str] = {}
    for line in text.splitlines():
        match = re.match(r"^\s*-?\s*([A-Za-z][A-Za-z ]{1,40})\s*:\s*(.*?)\s*$", line)
        if match:
            fields[match.group(1).strip()] = match.group(2).strip()
    return fields


def is_no_new_contact(value: object) -> bool:
    if isinstance(value, dict):
        status = value.get("status") or value.get("Status")
        return is_no_new_contact(status)
    normalized = re.sub(r"[^a-z0-9]+", "_", str(value or "").casefold()).strip("_")
    return normalized in {
        "no_new_contact",
        "no_new_contacts",
        "status_no_new_contact",
        "status_no_new_contacts",
    }


def message_domains(message: str) -> set[str]:
    domains: set[str] = set()
    for raw_url in URL_PATTERN.findall(message or ""):
        url = raw_url if "://" in raw_url else f"https://{raw_url}"
        hostname = (urlparse(url).hostname or "").casefold().rstrip(".")
        if hostname.startswith("www."):
            hostname = hostname[4:]
        if hostname:
            domains.add(hostname)
    return domains


def screening_decision(
    contact: dict[str, str], config: ScreeningConfig
) -> tuple[str, list[str]]:
    if is_no_new_contact(contact):
        return "empty", []

    name = normalize_name(contact.get("Name"))
    ip = str(contact.get("IP") or "").strip()
    country = str(contact.get("Country") or "").strip().upper()
    message = str(contact.get("Message") or "").strip()
    domains = message_domains(message)
    urls_present = bool(domains)
    promo_matches = [
        pattern.pattern for pattern in PROMOTIONAL_PATTERNS if pattern.search(message)
    ]

    block_reasons: list[str] = []
    if name and name in config.blocked_names:
        block_reasons.append("blocked_name")
    if ip and ip in config.blocked_ips:
        block_reasons.append("blocked_ip")
    if any(
        domain == blocked or domain.endswith(f".{blocked}")
        for domain in domains
        for blocked in config.blocked_domains
    ):
        block_reasons.append("blocked_link_domain")
    if urls_present and promo_matches:
        block_reasons.append("promotional_link")
    elif promo_matches and any("promo" in match.casefold() or "prize" in match.casefold() for match in promo_matches):
        block_reasons.append("promotional_spam")
    if country == "T1":
        block_reasons.append("tor_exit_country")
    elif country not in UNKNOWN_COUNTRIES and country not in config.allowed_countries:
        block_reasons.append("non_us_country")
    if block_reasons:
        return "blocked", sorted(set(block_reasons))

    review_reasons: list[str] = []
    if not contact.get("Name") or not contact.get("Email") or not message:
        review_reasons.append("missing_required_field")
    if country in UNKNOWN_COUNTRIES:
        review_reasons.append("unknown_country")
    if urls_present:
        review_reasons.append("unverified_link")
    if message and len(message) < config.minimum_message_length:
        review_reasons.append("message_too_short")
    if review_reasons:
        return "review", sorted(set(review_reasons))
    return "allowed", []


def append_audit(path: Path, contact: dict[str, str], decision: str, reasons: list[str]) -> None:
    record = {
        **contact,
        "screened_at": datetime.now(timezone.utc).isoformat(),
        "screening_status": decision,
        "screening_reasons": reasons,
        "source": "contact_screener",
    }
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("a", encoding="utf-8") as handle:
        fcntl.flock(handle.fileno(), fcntl.LOCK_EX)
        handle.write(json.dumps(record, sort_keys=True, ensure_ascii=False) + "\n")
        handle.flush()
        os.fsync(handle.fileno())
        fcntl.flock(handle.fileno(), fcntl.LOCK_UN)


def screen_contact(value: object, config: ScreeningConfig) -> dict[str, object]:
    contact = parse_contact(value)
    decision, reasons = screening_decision(contact, config)
    if decision == "empty":
        return {"status": "no_new_contacts", "screening_status": "empty"}

    append_audit(config.screened_path, contact, decision, reasons)
    if decision == "blocked":
        append_audit(config.blocked_path, contact, decision, reasons)
    elif decision == "review":
        append_audit(config.review_path, contact, decision, reasons)

    if decision != "allowed":
        return {
            "status": "no_new_contacts",
            "screening_status": decision,
            "screening_reasons": reasons,
        }
    return {
        **contact,
        "screening_status": "allowed",
        "screening_reasons": [],
    }


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Screen a contact before automatic response.")
    parser.add_argument("--input", help="Contact JSON or labeled text from the mail reader.")
    return parser.parse_args()


def main() -> dict[str, object]:
    args = parse_args()
    value = args.input
    if value is None and not sys.stdin.isatty():
        value = sys.stdin.read()
    outcome = screen_contact(value or "No New Contacts", ScreeningConfig.from_env())
    status = outcome.get("screening_status", "unknown")
    reasons = outcome.get("screening_reasons") or []
    reason_text = f" ({', '.join(str(reason) for reason in reasons)})" if reasons else ""
    print(f"Contact screening: {status}{reason_text}", flush=True)
    return outcome


if __name__ == "__main__":
    result = main()

from __future__ import annotations

import argparse
from dataclasses import dataclass
from datetime import datetime, timezone
from email.message import EmailMessage
import json
import os
import logging
from pathlib import Path
import re
import smtplib
import sys
from typing import Any


def _load_env_file(path: Path = Path(".env")) -> None:
    if not path.exists():
        return

    import os

    for raw_line in path.read_text(encoding="utf-8").splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue

        key, value = line.split("=", 1)
        os.environ.setdefault(key.strip(), value.strip().strip('"').strip("'"))


    unfilled = sorted(k for k, v in os.environ.items() if v.startswith("ENTER_") and v.endswith("_HERE"))
    if unfilled:
        raise SystemExit(f"Fill in {', '.join(unfilled)} in {path} before running this workflow.")


def _int_env(name: str, default: int) -> int:
    import os

    value = os.getenv(name)
    if value is None or not value.strip():
        return default
    return int(value)


def _bool_env(name: str, default: bool = False) -> bool:
    import os

    value = os.getenv(name)
    if value is None:
        return default
    return value.strip().lower() in {"1", "true", "yes", "y", "on"}


@dataclass(frozen=True)
class ContactResponderConfig:
    smtp_host: str
    smtp_port: int
    smtp_username: str
    smtp_password: str
    from_email: str
    from_name: str
    latest_contact_path: Path
    sent_contacts_path: Path
    blocked_contacts_path: Path
    blocked_contact_names: frozenset[str]
    require_screening: bool
    log_path: Path

    @classmethod
    def from_env(cls) -> "ContactResponderConfig":
        import os

        _load_env_file()
        username = os.getenv("SMTP_USERNAME") or os.getenv("EMAIL_USERNAME", "")
        password = os.getenv("SMTP_PASSWORD") or "".join(os.getenv("EMAIL_PASSWORD", "").split())

        return cls(
            smtp_host=os.getenv("SMTP_HOST", "smtp.gmail.com"),
            smtp_port=_int_env("SMTP_PORT", 587),
            smtp_username=username,
            smtp_password=password,
            from_email=os.getenv("CONTACT_RESPONSE_FROM_EMAIL", username),
            from_name=os.getenv("CONTACT_RESPONSE_FROM_NAME", ""),
            latest_contact_path=Path(os.getenv("LATEST_CONTACT_PATH", "data/latest_contact.json")),
            sent_contacts_path=Path(os.getenv("SENT_CONTACTS_PATH", "data/sent_contact_responses.jsonl")),
            blocked_contacts_path=Path(
                os.getenv("BLOCKED_CONTACTS_PATH", "data/blocked_contacts.jsonl")
            ),
            blocked_contact_names=frozenset(
                item.strip()
                for item in os.getenv(
                    "BLOCKED_CONTACT_NAMES", "RobertWew,HarryPhefs"
                ).split(",")
                if item.strip()
            ),
            require_screening=_bool_env("CONTACT_REQUIRE_SCREENING", True),
            log_path=Path(os.getenv("CONTACT_RESPONDER_LOG_PATH", "logs/contact_responder.log")),
        )


def setup_logging(log_path: Path) -> None:
    log_path.parent.mkdir(parents=True, exist_ok=True)
    logging.basicConfig(
        level=logging.INFO,
        format="%(asctime)s %(levelname)s %(message)s",
        handlers=[
            logging.FileHandler(log_path, encoding="utf-8"),
        ],
    )


def parse_contact_text(value: str) -> dict[str, str]:
    contact: dict[str, str] = {}
    key_map = {
        "name": "Name",
        "email": "Email",
        "company": "Company",
        "interested in": "Interested In",
        "message": "Message",
    }

    for line in value.splitlines():
        match = re.match(r"^\s*-?\s*([A-Za-z][A-Za-z ]{1,40})\s*:\s*(.*?)\s*$", line)
        if not match:
            continue

        normalized_key = re.sub(r"\s+", " ", match.group(1).strip().lower())
        if normalized_key in key_map:
            contact[key_map[normalized_key]] = match.group(2).strip()

    return contact


def is_no_new_contact_payload(value: Any) -> bool:
    if value is None:
        return False
    if isinstance(value, str):
        normalized = re.sub(r"[^a-z0-9]+", "_", value.strip().lower()).strip("_")
        return normalized in {"no_new_contact", "no_new_contacts"}
    if isinstance(value, dict):
        status = value.get("status") or value.get("Status")
        message = value.get("message") or value.get("result")
        return is_no_new_contact_payload(status) or is_no_new_contact_payload(message)
    return False


def parse_contact_input(value: str) -> dict[str, str]:
    text = value.strip()
    if not text:
        return {}
    try:
        payload = json.loads(text)
    except json.JSONDecodeError:
        if is_no_new_contact_payload(text):
            return {"Status": "no_new_contacts"}
        return parse_contact_text(text)
    if is_no_new_contact_payload(payload):
        return {"Status": "no_new_contacts"}
    if not isinstance(payload, dict):
        return {}
    return normalize_contact(payload)


def load_contact(args: argparse.Namespace, config: ContactResponderConfig) -> dict[str, str]:
    if args.contact_json:
        payload = json.loads(Path(args.contact_json).read_text(encoding="utf-8"))
        if not isinstance(payload, dict):
            raise ValueError(f"Contact JSON must contain an object: {args.contact_json}")
        return normalize_contact(payload)

    text = args.input or ""
    if not text and not sys.stdin.isatty():
        text = sys.stdin.read()
    if text.strip():
        return parse_contact_input(text)

    if config.latest_contact_path.exists():
        payload = json.loads(config.latest_contact_path.read_text(encoding="utf-8"))
        if not isinstance(payload, dict):
            raise ValueError(f"Latest contact JSON must contain an object: {config.latest_contact_path}")
        return normalize_contact(payload)

    return {"Status": "no_new_contacts"}


def normalize_contact(payload: dict[str, Any]) -> dict[str, str]:
    return {
        "Name": str(payload.get("Name") or payload.get("contact_name") or "").strip(),
        "Email": str(payload.get("Email") or payload.get("contact_email") or "").strip(),
        "Company": str(payload.get("Company") or payload.get("company") or "").strip(),
        "Interested In": str(payload.get("Interested In") or payload.get("interested_in") or "").strip(),
        "Message": str(payload.get("Message") or payload.get("message") or "").strip(),
        "IP": str(payload.get("IP") or payload.get("ip") or "").strip(),
        "Country": str(payload.get("Country") or payload.get("country") or "").strip().upper(),
        "Screening Status": str(
            payload.get("Screening Status") or payload.get("screening_status") or ""
        ).strip().lower(),
    }


def validate_contact(contact: dict[str, str]) -> None:
    if is_no_new_contact_payload(contact):
        return
    if not contact.get("Email"):
        raise ValueError("Contact is missing Email.")
    if "@" not in contact["Email"]:
        raise ValueError(f"Contact Email does not look valid: {contact['Email']!r}")


def normalize_contact_name(value: object) -> str:
    return "".join(character for character in str(value or "").casefold() if character.isalnum())


def is_blocked_contact(contact: dict[str, str], config: ContactResponderConfig) -> bool:
    blocked_names = {
        normalize_contact_name(name)
        for name in config.blocked_contact_names
        if normalize_contact_name(name)
    }
    return normalize_contact_name(contact.get("Name")) in blocked_names


def append_blocked_record(
    path: Path,
    contact: dict[str, str],
    reasons: list[str] | None = None,
) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    record = {
        "contact_email": contact.get("Email", ""),
        "contact_name": contact.get("Name", ""),
        "blocked_at": datetime.now(timezone.utc).isoformat(),
        "spam_reasons": reasons or ["blocked_name"],
        "source": "contact_responder",
        "status": "blocked_spam",
    }
    with path.open("a", encoding="utf-8") as handle:
        handle.write(json.dumps(record, sort_keys=True) + "\n")


def build_response(contact: dict[str, str], config: ContactResponderConfig) -> EmailMessage:
    name = contact.get("Name") or "there"
    message = EmailMessage()
    message["To"] = contact["Email"]
    message["From"] = f"{config.from_name} <{config.from_email}>" if config.from_name else config.from_email
    business = os.getenv("CONTACT_BUSINESS_NAME", "our team")
    signature = os.getenv("CONTACT_SIGNATURE", config.from_name or business)
    message["Subject"] = f"Thanks for reaching out to {business}"
    message.set_content(
        "\n".join(
            [
                f"Hello {name},",
                "",
                f"Thank you for reaching out to {business}. I received your message and will get back to you at my earliest convenience.",
                "",
                "Best regards,",
                *signature.split("|"),
            ]
        )
    )
    return message


def send_message(message: EmailMessage, config: ContactResponderConfig) -> None:
    if not config.smtp_username or not config.smtp_password:
        raise ValueError("SMTP credentials are missing. Set SMTP_USERNAME/SMTP_PASSWORD or EMAIL_USERNAME/EMAIL_PASSWORD.")

    with smtplib.SMTP(config.smtp_host, config.smtp_port) as smtp:
        smtp.starttls()
        smtp.login(config.smtp_username, config.smtp_password)
        smtp.send_message(message)


def sent_contact_key(contact: dict[str, str]) -> str:
    return str(contact.get("Email") or "").strip().lower()


def already_sent_response(path: Path, contact: dict[str, str]) -> bool:
    key = sent_contact_key(contact)
    if not key or not path.exists():
        return False
    with path.open("r", encoding="utf-8") as handle:
        for line in handle:
            try:
                record = json.loads(line)
            except json.JSONDecodeError:
                continue
            if str(record.get("contact_email") or "").strip().lower() == key and record.get("status") == "sent":
                return True
    return False


def append_sent_record(path: Path, contact: dict[str, str]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    record = {
        "contact_email": contact["Email"],
        "contact_name": contact.get("Name", ""),
        "sent_at": datetime.now(timezone.utc).isoformat(),
        "status": "sent",
    }
    with path.open("a", encoding="utf-8") as handle:
        handle.write(json.dumps(record, sort_keys=True) + "\n")


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Send an initial acknowledgment email to a new contact.")
    parser.add_argument("--input", help="Contact text from the mail reader output.")
    parser.add_argument("--contact-json", help="Path to a contact JSON file. Defaults to LATEST_CONTACT_PATH.")
    return parser.parse_args()


def main() -> None:
    try:
        args = parse_args()
        config = ContactResponderConfig.from_env()
        setup_logging(config.log_path)

        contact = load_contact(args, config)
        if is_no_new_contact_payload(contact):
            logging.info("No new contacts from mail reader; skipping contact response.")
            print("No New Contacts", flush=True)
            return
        validate_contact(contact)
        if is_blocked_contact(contact, config):
            append_blocked_record(config.blocked_contacts_path, contact)
            logging.warning(
                "Blocked contact response before SMTP. Name=%r Email=%r",
                contact.get("Name", ""),
                contact.get("Email", ""),
            )
            print("Blocked Spam", flush=True)
            return
        if config.require_screening and contact.get("Screening Status") != "allowed":
            append_blocked_record(
                config.blocked_contacts_path,
                contact,
                ["screening_required"],
            )
            logging.warning(
                "Refused unscreened contact before SMTP. Name=%r Email=%r",
                contact.get("Name", ""),
                contact.get("Email", ""),
            )
            print("Screening Required", flush=True)
            return
        if already_sent_response(config.sent_contacts_path, contact):
            logging.info("Contact response already sent to %s; skipping duplicate.", contact["Email"])
            print("Already Sent", flush=True)
            return
        message = build_response(contact, config)

        logging.info("Prepared contact response for %s", contact["Email"])
        send_message(message, config)
        logging.info("Sent contact response to %s", contact["Email"])

        append_sent_record(config.sent_contacts_path, contact)
        print("message sent", flush=True)
    except Exception:
        logging.exception("Contact response failed")
        print("message failed", flush=True)
        raise SystemExit(1)


if __name__ == "__main__":
    main()
